  if(action==='style'){ws.data.style=value;ws.data.personalBrand.enabled=false;for(const s of ws.data.sections){delete s.variant}ws.data.heroVariant={Minimal:'Editorial',Editorial:'Editorial',Bold:'Statement',Cinematic:'Visual',Gallery:'Visual','Clean Professional':'Split'}[value];ws.data.workVariant=value==='Gallery'?'Masonry':value==='Cinematic'?'Horizontal':'Grid';await saveWorkspace();toast('Style updated.');return styles()}
  if(['ready','archive','duplicate'].includes(action)){const p=ws.data.projects.find(p=>p.id===value);if(action==='ready'){p.status=p.status==='Published'?'Draft':'Published';if(p.visibility!=='Password protected')p.visibility=p.status==='Published'?'Public':'Private';p.featured=p.status==='Published'}if(action==='archive')p.status=p.status==='Archived'?'Draft':'Archived';if(action==='duplicate'){const copy=structuredClone(p);copy.id=crypto.randomUUID();copy.title+=' — copy';copy.status='Draft';copy.visibility='Private';copy.blocks.forEach(b=>b.id=crypto.randomUUID());ws.data.projects.push(copy)}await saveWorkspace();return projects()}
